// Fastify's adapter, a subpath of the `@trpc/server` stub: a plugin handed to
// `register` with its prefix and the tree under `trpcOptions`, never called.

import type { AnyRouter } from '../index.js';

export interface FastifyTRPCPluginOptions {
  prefix?: string;
  trpcOptions: { router: AnyRouter; createContext?: () => unknown };
}

export declare function fastifyTRPCPlugin(instance: unknown, options: FastifyTRPCPluginOptions): Promise<void>;
